702	  @Test (timeout = 300000)
703	  public void testUpgradeCommand() throws Exception {
704	    final String finalizedMsg = "Upgrade finalized for.*";
705	    final String notFinalizedMsg = "Upgrade not finalized for.*";
706	    final String failMsg = "Getting upgrade status failed for.*" + newLine +
707	        "upgrade: .*";
708	    final String finalizeSuccessMsg = "Finalize upgrade successful for.*";
709	
710	    setUpHaCluster(false);
711	    MiniDFSCluster dfsCluster = cluster.getDfsCluster();
712	
713	    // Before upgrade is initialized, the query should return upgrade
714	    // finalized (as no upgrade is in progress)
715	    String message = finalizedMsg + newLine + finalizedMsg + newLine;
716	    verifyUpgradeQueryOutput(message, 0);
717	
718	    // Shutdown the NNs
719	    dfsCluster.shutdownNameNode(0);
720	    dfsCluster.shutdownNameNode(1);
721	
722	    // Start NN1 with -upgrade option
723	    dfsCluster.getNameNodeInfos()[0].setStartOpt(
724	        HdfsServerConstants.StartupOption.UPGRADE);
725	    dfsCluster.restartNameNode(0, true);
726	
727	    // Running -upgrade query should return "not finalized" for NN1 and
728	    // connection exception for NN2 (as NN2 is down)
729	    message = notFinalizedMsg + newLine;
730	    verifyUpgradeQueryOutput(message, -1);
731	    String errorMsg =  failMsg + newLine;
732	    verifyUpgradeQueryOutput(errorMsg, -1);
733	
734	    // Bootstrap the standby (NN2) with the upgraded info.
735	    int rc = BootstrapStandby.run(
736	        new String[]{"-force"},
737	        dfsCluster.getConfiguration(1));
738	    assertEquals(0, rc);
739	    out.reset();
740	
741	    // Restart NN2.
742	    dfsCluster.restartNameNode(1);
743	
744	    // Both NNs should return "not finalized" msg for -upgrade query
745	    message = notFinalizedMsg + newLine + notFinalizedMsg + newLine;
746	    verifyUpgradeQueryOutput(message, 0);
747	
748	    // Finalize the upgrade
749	    int exitCode = admin.run(new String[] {"-upgrade", "finalize"});
750	    assertEquals(err.toString().trim(), 0, exitCode);
751	    message = finalizeSuccessMsg + newLine + finalizeSuccessMsg + newLine;
752	    assertOutputMatches(message);
753	
754	    // NNs should return "upgrade finalized" msg
755	    message = finalizedMsg + newLine + finalizedMsg + newLine;
756	    verifyUpgradeQueryOutput(message, 0);
757	  }
758	
759	  private void verifyUpgradeQueryOutput(String message, int expected) throws
760	      Exception {
761	    int exitCode = admin.run(new String[] {"-upgrade", "query"});
762	    assertEquals(err.toString().trim(), expected, exitCode);
763	    assertOutputMatches(message);
764	  }
